Check the return value of `SecItemAdd` and at minimum log the failure:
```swift
let status = SecItemAdd(addQuery as CFDictionary, nil)
if status != errSecSuccess {
    // Log or assert; the token was deleted but not re-written
}
```
Alternatively, use `SecItemUpdate` when the item already exists to make it atomic.

Prefer update-or-add: try SecItemUpdate; on errSecItemNotFound, SecItemAdd. Check OSStatus on both paths and log/assert non-success (except item-not-found on delete). Example shape:

func setSecureString(_ value: String?, forKey key: String) {
    let base: [CFString: Any] = [kSecClass: kSecClassGenericPassword, kSecAttrAccount: key]
    guard let value, let data = value.data(using: .utf8) else {
        SecItemDelete(base as CFDictionary)
        return
    }
    let update = SecItemUpdate(base as CFDictionary, [kSecValueData: data] as CFDictionary)
    if update == errSecItemNotFound {
        var add = base
        add[kSecValueData] = data
        add[kSecAttrAccessible] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        let status = SecItemAdd(add as CFDictionary, nil)
        assert(status == errSecSuccess || status == errSecDuplicateItem)
    }
}
